window.DINOS = [{"slug":"eoraptor","nom":"Eoraptor","periode":"trias","famille":"theropodes","regime":"omnivore","longueur":1,"poids":10,"vitesse":30,"ageDebut":231,"ageFin":228,"lieux":["Amérique du Sud"],"comparaison":"aussi grand qu’un gros chat","accroche":"L’un des tout premiers dinosaures de l’histoire de la Terre !","vraiDino":true,"saviezVous":["Son squelette a été trouvé presque complet, ce qui est très rare pour un animal aussi vieux.","Il tenait dans les bras d’un enfant : à peine 1 mètre de long, la queue comprise.","Son nom veut dire « voleur de l’aube » car il vivait à l’aube du règne des dinosaures."],"img":"assets/img/dinos/eoraptor.svg","imgPuzzle":"assets/img/puzzle/eoraptor.svg","url":"dinosaures/eoraptor.html"},{"slug":"herrerasaurus","nom":"Herrerasaurus","periode":"trias","famille":"theropodes","regime":"carnivore","longueur":5,"poids":250,"vitesse":30,"ageDebut":231,"ageFin":229,"lieux":["Amérique du Sud"],"comparaison":"aussi long qu’une petite voiture","accroche":"Le premier grand chasseur à deux pattes du monde des dinosaures.","vraiDino":true,"saviezVous":["Ce n’est pas un berger de moutons qui l’a trouvé… mais bien un éleveur nommé Herrera !","À son époque, les dinosaures représentaient moins d’un animal sur dix.","Il courait probablement plus vite qu’un humain adulte."],"img":"assets/img/dinos/herrerasaurus.svg","imgPuzzle":"assets/img/puzzle/herrerasaurus.svg","url":"dinosaures/herrerasaurus.html"},{"slug":"plateosaurus","nom":"Plateosaurus","periode":"trias","famille":"sauropodomorphes","regime":"herbivore","longueur":8,"poids":4000,"vitesse":15,"ageDebut":214,"ageFin":204,"lieux":["Europe","Groenland"],"comparaison":"aussi long qu’un minibus","accroche":"Le géant du Trias, ancêtre lointain des immenses sauropodes.","vraiDino":true,"saviezVous":["C’est le premier dinosaure découvert en Allemagne, en 1837.","Il avalait des cailloux pour broyer les plantes dans son estomac : on les appelle des gastrolithes.","Certains individus grandissaient plus vite que d’autres, un peu comme chez les humains."],"img":"assets/img/dinos/plateosaurus.svg","imgPuzzle":"assets/img/puzzle/plateosaurus.svg","url":"dinosaures/plateosaurus.html"},{"slug":"coelophysis","nom":"Coelophysis","periode":"trias","famille":"theropodes","regime":"carnivore","longueur":3,"poids":25,"vitesse":40,"ageDebut":216,"ageFin":196,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’un canapé","accroche":"Un chasseur fin comme un lévrier, qui vivait en bandes.","vraiDino":true,"saviezVous":["C’est le fossile officiel de l’État du Nouveau-Mexique.","Un Coelophysis est parti dans l’espace en 1998 à bord de la navette Endeavour !","Il pesait à peine plus lourd qu’un gros chien."],"img":"assets/img/dinos/coelophysis.svg","imgPuzzle":"assets/img/puzzle/coelophysis.svg","url":"dinosaures/coelophysis.html"},{"slug":"dilophosaurus","nom":"Dilophosaurus","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":7,"poids":400,"vitesse":30,"ageDebut":193,"ageFin":183,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’un grand van","accroche":"Le dinosaure au casque double, star incomprise du cinéma.","vraiDino":true,"saviezVous":["Ses empreintes de pas ont été retrouvées avant son squelette.","Le vrai Dilophosaurus était 3 fois plus grand que celui du film Jurassic Park.","Son museau portait une encoche, comme celui des crocodiles."],"img":"assets/img/dinos/dilophosaurus.svg","imgPuzzle":"assets/img/puzzle/dilophosaurus.svg","url":"dinosaures/dilophosaurus.html"},{"slug":"cryolophosaurus","nom":"Cryolophosaurus","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":6.5,"poids":450,"vitesse":28,"ageDebut":194,"ageFin":188,"lieux":["Antarctique"],"comparaison":"aussi long qu’un grand van","accroche":"Le seul grand carnivore découvert sur le continent de glace !","vraiDino":true,"saviezVous":["Il a fallu utiliser des marteaux-piqueurs pour extraire ses os de la roche gelée.","À son époque, l’Antarctique était couvert de forêts et de fougères.","Son surnom officieux est « Elvisaurus »."],"img":"assets/img/dinos/cryolophosaurus.svg","imgPuzzle":"assets/img/puzzle/cryolophosaurus.svg","url":"dinosaures/cryolophosaurus.html"},{"slug":"allosaurus","nom":"Allosaurus","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":9,"poids":2000,"vitesse":33,"ageDebut":155,"ageFin":145,"lieux":["Amérique du Nord","Europe"],"comparaison":"aussi long qu’un camion de pompiers","accroche":"Le lion du Jurassique : rapide, puissant et très nombreux.","vraiDino":true,"saviezVous":["Plus de 60 squelettes d’Allosaurus ont été retrouvés : c’est l’un des dinosaures les mieux connus.","Une vertèbre de Stégosaure a été retrouvée percée par une pointe de queue… et une dent d’Allosaurus plantée dedans !","Il possédait deux petites cornes au-dessus des yeux."],"img":"assets/img/dinos/allosaurus.svg","imgPuzzle":"assets/img/puzzle/allosaurus.svg","url":"dinosaures/allosaurus.html"},{"slug":"ceratosaurus","nom":"Ceratosaurus","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":6,"poids":900,"vitesse":28,"ageDebut":153,"ageFin":148,"lieux":["Amérique du Nord","Afrique","Europe"],"comparaison":"aussi long qu’un grand 4x4","accroche":"Une corne sur le nez et une rangée d’écailles sur le dos.","vraiDino":true,"saviezVous":["Sa corne était trop fragile pour se battre : elle servait surtout à parader.","Sa queue était aplatie sur les côtés, comme celle d’un crocodile nageur.","Il avait 4 doigts à chaque main, alors que l’Allosaurus n’en avait que 3."],"img":"assets/img/dinos/ceratosaurus.svg","imgPuzzle":"assets/img/puzzle/ceratosaurus.svg","url":"dinosaures/ceratosaurus.html"},{"slug":"stegosaurus","nom":"Stegosaurus","periode":"jurassique","famille":"thyreophores","regime":"herbivore","longueur":9,"poids":5000,"vitesse":7,"ageDebut":155,"ageFin":145,"lieux":["Amérique du Nord","Europe"],"comparaison":"aussi long qu’un bus, avec une tête minuscule","accroche":"Des plaques sur le dos et quatre pointes au bout de la queue !","vraiDino":true,"saviezVous":["Le mot « thagomizer » vient d’une bande dessinée humoristique… et les scientifiques l’ont vraiment adopté !","Ses plaques pouvaient peut-être changer de couleur quand il s’énervait, en se remplissant de sang.","Son cerveau pesait environ 80 grammes, pour un corps de 5 tonnes."],"img":"assets/img/dinos/stegosaurus.svg","imgPuzzle":"assets/img/puzzle/stegosaurus.svg","url":"dinosaures/stegosaurus.html"},{"slug":"kentrosaurus","nom":"Kentrosaurus","periode":"jurassique","famille":"thyreophores","regime":"herbivore","longueur":4.5,"poids":1000,"vitesse":8,"ageDebut":154,"ageFin":151,"lieux":["Afrique"],"comparaison":"aussi long qu’une petite voiture","accroche":"Le cousin africain du Stégosaure, hérissé de piques de la tête à la queue.","vraiDino":true,"saviezVous":["Beaucoup de ses os ont été détruits pendant la Seconde Guerre mondiale, à Berlin.","Il pesait 5 fois moins qu’un Stégosaure.","Son nom grec « kentron » signifie « aiguillon »."],"img":"assets/img/dinos/kentrosaurus.svg","imgPuzzle":"assets/img/puzzle/kentrosaurus.svg","url":"dinosaures/kentrosaurus.html"},{"slug":"diplodocus","nom":"Diplodocus","periode":"jurassique","famille":"sauropodes","regime":"herbivore","longueur":26,"poids":15000,"vitesse":10,"ageDebut":154,"ageFin":148,"lieux":["Amérique du Nord"],"comparaison":"aussi long que deux bus mis bout à bout","accroche":"Un cou immense devant, un fouet géant derrière : 26 mètres de long !","vraiDino":true,"saviezVous":["Un moulage de son squelette, surnommé « Dippy », a été offert à des musées du monde entier.","Il ne mâchait pas : il avalait tout rond et laissait son estomac faire le travail.","Ses narines étaient placées très haut sur le crâne, entre les yeux."],"img":"assets/img/dinos/diplodocus.svg","imgPuzzle":"assets/img/puzzle/diplodocus.svg","url":"dinosaures/diplodocus.html"},{"slug":"apatosaurus","nom":"Apatosaurus","periode":"jurassique","famille":"sauropodes","regime":"herbivore","longueur":22,"poids":25000,"vitesse":12,"ageDebut":152,"ageFin":151,"lieux":["Amérique du Nord"],"comparaison":"aussi lourd que 5 éléphants","accroche":"Le colosse au cou épais, longtemps appelé « Brontosaure ».","vraiDino":true,"saviezVous":["Il devait manger plusieurs centaines de kilos de plantes chaque jour.","Ses os contenaient des cavités remplies d’air, comme ceux des oiseaux, pour alléger son squelette.","Son nom signifie « trompeur » parce que ses os ressemblaient à ceux d’un animal marin."],"img":"assets/img/dinos/apatosaurus.svg","imgPuzzle":"assets/img/puzzle/apatosaurus.svg","url":"dinosaures/apatosaurus.html"},{"slug":"brachiosaurus","nom":"Brachiosaurus","periode":"jurassique","famille":"sauropodes","regime":"herbivore","longueur":22,"poids":40000,"vitesse":12,"ageDebut":154,"ageFin":150,"lieux":["Amérique du Nord","Afrique"],"comparaison":"aussi haut qu’un immeuble de 4 étages","accroche":"La girafe des dinosaures : sa tête montait à 13 mètres de haut !","vraiDino":true,"saviezVous":["Une seule de ses vertèbres pouvait mesurer plus d’un mètre.","Un squelette monté à Berlin (de son cousin Giraffatitan) est le plus grand du monde exposé dans un musée.","On pense qu’il tenait la tête haute en permanence, comme une girafe."],"img":"assets/img/dinos/brachiosaurus.svg","imgPuzzle":"assets/img/puzzle/brachiosaurus.svg","url":"dinosaures/brachiosaurus.html"},{"slug":"compsognathus","nom":"Compsognathus","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":1,"poids":3,"vitesse":40,"ageDebut":150,"ageFin":145,"lieux":["Europe"],"comparaison":"aussi grand qu’une poule","accroche":"Grand comme une poule, mais rapide comme l’éclair !","vraiDino":true,"saviezVous":["Un fossile a été trouvé en France, près de Canjuers dans le Var.","Il pesait à peine 3 kilos, comme un petit chat.","Pendant longtemps, c’était le plus petit dinosaure connu."],"img":"assets/img/dinos/compsognathus.svg","imgPuzzle":"assets/img/puzzle/compsognathus.svg","url":"dinosaures/compsognathus.html"},{"slug":"archaeopteryx","nom":"Archaeopteryx","periode":"jurassique","famille":"theropodes","regime":"carnivore","longueur":0.5,"poids":1,"vitesse":25,"ageDebut":150,"ageFin":148,"lieux":["Europe"],"comparaison":"aussi grand qu’un corbeau","accroche":"Le chaînon entre les dinosaures et les oiseaux : il avait des plumes ET des dents !","vraiDino":true,"saviezVous":["Ses plumes sont si bien conservées qu’on distingue chaque barbule dans la pierre.","Une analyse chimique suggère que ses plumes étaient noires.","Il n’existe qu’une douzaine de spécimens dans le monde entier."],"img":"assets/img/dinos/archaeopteryx.svg","imgPuzzle":"assets/img/puzzle/archaeopteryx.svg","url":"dinosaures/archaeopteryx.html"},{"slug":"pterodactylus","nom":"Pterodactylus","periode":"jurassique","famille":"pterosaures","regime":"carnivore","longueur":1,"poids":2,"vitesse":45,"ageDebut":151,"ageFin":148,"lieux":["Europe"],"comparaison":"aussi large qu’une grande mouette","accroche":"Un reptile volant… mais surtout : ce n’est PAS un dinosaure !","vraiDino":false,"saviezVous":["C’est le tout premier ptérosaure jamais décrit par la science, en 1784.","Ses os étaient creux et fins comme du papier pour l’alléger.","Certains ptérosaures marchaient à quatre pattes, en repliant leurs ailes."],"img":"assets/img/dinos/pterodactylus.svg","imgPuzzle":"assets/img/puzzle/pterodactylus.svg","url":"dinosaures/pterodactylus.html"},{"slug":"ichthyosaurus","nom":"Ichthyosaurus","periode":"jurassique","famille":"reptiles-marins","regime":"carnivore","longueur":3,"poids":200,"vitesse":40,"ageDebut":199,"ageFin":190,"lieux":["Europe"],"comparaison":"aussi long qu’un dauphin","accroche":"Un reptile marin en forme de dauphin — et pas un dinosaure non plus !","vraiDino":false,"saviezVous":["Mary Anning, une jeune fille anglaise de 12 ans, a découvert le premier crâne complet en 1811.","Il devait remonter respirer à la surface, comme une baleine.","Ses bébés naissaient la queue en premier pour ne pas se noyer."],"img":"assets/img/dinos/ichthyosaurus.svg","imgPuzzle":"assets/img/puzzle/ichthyosaurus.svg","url":"dinosaures/ichthyosaurus.html"},{"slug":"tyrannosaurus","nom":"Tyrannosaurus rex","periode":"cretace","famille":"theropodes","regime":"carnivore","longueur":12,"poids":8000,"vitesse":25,"ageDebut":68,"ageFin":66,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’un bus scolaire","accroche":"Le plus célèbre de tous : 12 mètres, 8 tonnes et la morsure la plus puissante de l’histoire.","vraiDino":true,"saviezVous":["Le squelette le plus complet s’appelle « Sue » et se trouve à Chicago.","Un T-rex pouvait vivre une trentaine d’années.","Bébé, il était couvert d’un duvet de plumes, comme un poussin géant.","Il ne pouvait pas courir très vite : à sa taille, tomber l’aurait tué."],"img":"assets/img/dinos/tyrannosaurus.svg","imgPuzzle":"assets/img/puzzle/tyrannosaurus.svg","url":"dinosaures/tyrannosaurus.html"},{"slug":"triceratops","nom":"Triceratops","periode":"cretace","famille":"ceratopsiens","regime":"herbivore","longueur":9,"poids":12000,"vitesse":25,"ageDebut":68,"ageFin":66,"lieux":["Amérique du Nord"],"comparaison":"aussi lourd que 3 voitures","accroche":"Trois cornes, une collerette géante et un caractère bien trempé.","vraiDino":true,"saviezVous":["Certaines collerettes retrouvées portent des cicatrices : les Triceratops se battaient entre eux, corne contre corne.","Il remplaçait ses dents usées toute sa vie, comme un requin.","C’est le fossile officiel de l’État du Wyoming."],"img":"assets/img/dinos/triceratops.svg","imgPuzzle":"assets/img/puzzle/triceratops.svg","url":"dinosaures/triceratops.html"},{"slug":"velociraptor","nom":"Velociraptor","periode":"cretace","famille":"raptors","regime":"carnivore","longueur":2,"poids":15,"vitesse":40,"ageDebut":75,"ageFin":71,"lieux":["Asie"],"comparaison":"aussi gros qu’un dindon","accroche":"Attention : le vrai Vélociraptor avait la taille d’un dindon… et des plumes !","vraiDino":true,"saviezVous":["Il était couvert de plumes, comme un aigle sans ailes de vol.","Son cerveau était gros pour un dinosaure : c’était un animal futé.","Le « raptor » des films ressemble davantage à son cousin américain Deinonychus."],"img":"assets/img/dinos/velociraptor.svg","imgPuzzle":"assets/img/puzzle/velociraptor.svg","url":"dinosaures/velociraptor.html"},{"slug":"deinonychus","nom":"Deinonychus","periode":"cretace","famille":"raptors","regime":"carnivore","longueur":3.4,"poids":70,"vitesse":40,"ageDebut":115,"ageFin":108,"lieux":["Amérique du Nord"],"comparaison":"aussi grand qu’un gros berger allemand, en plus long","accroche":"Le raptor qui a changé la façon dont on imagine les dinosaures.","vraiDino":true,"saviezVous":["C’est lui qui a inspiré les « raptors » de Jurassic Park, sous le nom de Vélociraptor.","Sa griffe du pied mesurait 12 cm, plus longue que ton pouce.","Il avait des plumes, comme tous les raptors connus."],"img":"assets/img/dinos/deinonychus.svg","imgPuzzle":"assets/img/puzzle/deinonychus.svg","url":"dinosaures/deinonychus.html"},{"slug":"microraptor","nom":"Microraptor","periode":"cretace","famille":"raptors","regime":"carnivore","longueur":0.8,"poids":1,"vitesse":30,"ageDebut":125,"ageFin":120,"lieux":["Asie"],"comparaison":"aussi grand qu’un pigeon","accroche":"Un dinosaure à QUATRE ailes, noir et brillant comme un corbeau.","vraiDino":true,"saviezVous":["On connaît sa couleur exacte : noir irisé, un cas très rare en paléontologie.","Dans son estomac, on a retrouvé un poisson, un oiseau et un petit mammifère.","Plus de 300 fossiles ont été découverts en Chine."],"img":"assets/img/dinos/microraptor.svg","imgPuzzle":"assets/img/puzzle/microraptor.svg","url":"dinosaures/microraptor.html"},{"slug":"spinosaurus","nom":"Spinosaurus","periode":"cretace","famille":"theropodes","regime":"piscivore","longueur":15,"poids":7400,"vitesse":20,"ageDebut":99,"ageFin":93,"lieux":["Afrique"],"comparaison":"aussi long qu’un semi-remorque","accroche":"Le plus grand carnivore terrestre de tous les temps… et il vivait dans l’eau !","vraiDino":true,"saviezVous":["Ses narines étaient placées haut sur le crâne pour respirer en nageant.","Sa voile servait peut-être à parader, ou à régler sa température.","Ses os étaient denses et lourds, comme ceux des pingouins, pour aider à plonger."],"img":"assets/img/dinos/spinosaurus.svg","imgPuzzle":"assets/img/puzzle/spinosaurus.svg","url":"dinosaures/spinosaurus.html"},{"slug":"baryonyx","nom":"Baryonyx","periode":"cretace","famille":"theropodes","regime":"piscivore","longueur":9,"poids":1700,"vitesse":25,"ageDebut":130,"ageFin":125,"lieux":["Europe"],"comparaison":"aussi long qu’un camion de pompiers","accroche":"Un pêcheur à griffe géante, cousin du Spinosaure.","vraiDino":true,"saviezVous":["C’est le premier dinosaure mangeur de poissons identifié avec certitude.","Son museau comptait deux fois plus de dents que celui d’un T-rex.","Le carrier amateur qui l’a trouvé s’appelait William Walker : l’espèce porte son nom, Baryonyx walkeri."],"img":"assets/img/dinos/baryonyx.svg","imgPuzzle":"assets/img/puzzle/baryonyx.svg","url":"dinosaures/baryonyx.html"},{"slug":"giganotosaurus","nom":"Giganotosaurus","periode":"cretace","famille":"theropodes","regime":"carnivore","longueur":13,"poids":8200,"vitesse":30,"ageDebut":99,"ageFin":95,"lieux":["Amérique du Sud"],"comparaison":"aussi long qu’un bus articulé","accroche":"Un rival du T-rex, encore plus long, tout au bout du monde.","vraiDino":true,"saviezVous":["Il a été trouvé par un mécanicien argentin en promenade, Rubén Carolini.","Son cerveau avait la forme d’une banane.","Il courait peut-être à 50 km/h, plus vite que le T-rex."],"img":"assets/img/dinos/giganotosaurus.svg","imgPuzzle":"assets/img/puzzle/giganotosaurus.svg","url":"dinosaures/giganotosaurus.html"},{"slug":"carnotaurus","nom":"Carnotaurus","periode":"cretace","famille":"theropodes","regime":"carnivore","longueur":8,"poids":1500,"vitesse":50,"ageDebut":72,"ageFin":69,"lieux":["Amérique du Sud"],"comparaison":"aussi long qu’un bus de ville","accroche":"Deux cornes de taureau, des bras ridicules… et une vitesse folle !","vraiDino":true,"saviezVous":["On connaît sa peau écailleuse dans le détail, un cas rare.","Ses bras étaient si courts qu’il ne pouvait pas atteindre sa propre bouche.","Son cou était très musclé pour encaisser les chocs de tête."],"img":"assets/img/dinos/carnotaurus.svg","imgPuzzle":"assets/img/puzzle/carnotaurus.svg","url":"dinosaures/carnotaurus.html"},{"slug":"ankylosaurus","nom":"Ankylosaurus","periode":"cretace","famille":"thyreophores","regime":"herbivore","longueur":8,"poids":6000,"vitesse":10,"ageDebut":68,"ageFin":66,"lieux":["Amérique du Nord"],"comparaison":"aussi large qu’une voiture, mais bien plus lourd","accroche":"Un char d’assaut vivant, avec une massue au bout de la queue.","vraiDino":true,"saviezVous":["Sa massue était faite de vertèbres soudées entre elles, d’où son nom « lézard soudé ».","Ses côtes étaient fusionnées à son armure : un vrai exosquelette.","Son gros intestin fermentait les plantes… il devait produire beaucoup de gaz !"],"img":"assets/img/dinos/ankylosaurus.svg","imgPuzzle":"assets/img/puzzle/ankylosaurus.svg","url":"dinosaures/ankylosaurus.html"},{"slug":"parasaurolophus","nom":"Parasaurolophus","periode":"cretace","famille":"hadrosaures","regime":"herbivore","longueur":10,"poids":3500,"vitesse":25,"ageDebut":76,"ageFin":73,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’un autocar","accroche":"Le trombone des dinosaures : sa crête servait de trompette !","vraiDino":true,"saviezVous":["On a pu recréer son cri grâce à des scanners médicaux de sa crête.","Il possédait plus de 500 dents empilées dans sa bouche.","Les jeunes avaient une toute petite crête qui grandissait avec l’âge."],"img":"assets/img/dinos/parasaurolophus.svg","imgPuzzle":"assets/img/puzzle/parasaurolophus.svg","url":"dinosaures/parasaurolophus.html"},{"slug":"maiasaura","nom":"Maiasaura","periode":"cretace","famille":"hadrosaures","regime":"herbivore","longueur":9,"poids":3000,"vitesse":25,"ageDebut":77,"ageFin":76,"lieux":["Amérique du Nord"],"comparaison":"aussi long que deux voitures mises bout à bout","accroche":"La « bonne mère » : le premier dinosaure dont on a prouvé qu’il élevait ses petits.","vraiDino":true,"saviezVous":["En 1985, un morceau d’os et de coquille d’œuf de Maiasaura est parti dans l’espace avec un astronaute : c’est le premier dinosaure de l’espace !","Les nids étaient espacés d’environ 7 mètres, un peu moins que la longueur d’un adulte : chaque maman avait juste la place de s’occuper des siens.","Son nom se termine par « saura » et non par « saurus » : c’est un nom au féminin, en l’honneur des mamans.","C’est le fossile officiel de l’État du Montana."],"img":"assets/img/dinos/maiasaura.svg","imgPuzzle":"assets/img/puzzle/maiasaura.svg","url":"dinosaures/maiasaura.html"},{"slug":"iguanodon","nom":"Iguanodon","periode":"cretace","famille":"hadrosaures","regime":"herbivore","longueur":10,"poids":3500,"vitesse":24,"ageDebut":126,"ageFin":122,"lieux":["Europe"],"comparaison":"aussi long qu’un autocar","accroche":"L’un des tout premiers dinosaures découverts… avec un pouce en forme de poignard.","vraiDino":true,"saviezVous":["Ses dents ressemblaient à celles d’un iguane vivant : d’où son nom.","Les 38 squelettes de Bernissart sont exposés à Bruxelles.","Son cinquième doigt était préhensile, capable d’attraper des branches."],"img":"assets/img/dinos/iguanodon.svg","imgPuzzle":"assets/img/puzzle/iguanodon.svg","url":"dinosaures/iguanodon.html"},{"slug":"pachycephalosaurus","nom":"Pachycephalosaurus","periode":"cretace","famille":"pachycephalosaures","regime":"herbivore","longueur":4.5,"poids":450,"vitesse":30,"ageDebut":70,"ageFin":66,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’une petite voiture","accroche":"Un casque en os de 25 cm d’épaisseur sur le crâne !","vraiDino":true,"saviezVous":["Les jeunes avaient une tête plate qui bombait en grandissant.","Son nom est l’un des plus longs et des plus difficiles à prononcer du monde des dinosaures.","Il courait vite sur ses deux pattes arrière."],"img":"assets/img/dinos/pachycephalosaurus.svg","imgPuzzle":"assets/img/puzzle/pachycephalosaurus.svg","url":"dinosaures/pachycephalosaurus.html"},{"slug":"styracosaurus","nom":"Styracosaurus","periode":"cretace","famille":"ceratopsiens","regime":"herbivore","longueur":5.5,"poids":2700,"vitesse":25,"ageDebut":75,"ageFin":74,"lieux":["Amérique du Nord"],"comparaison":"aussi long qu’un grand van","accroche":"Une couronne de six grandes pointes autour de la tête : un vrai soleil vivant.","vraiDino":true,"saviezVous":["Chaque individu avait une disposition de pointes légèrement différente.","Il est très proche cousin du Triceratops.","Son bec pouvait couper des branches aussi dures qu’un sécateur."],"img":"assets/img/dinos/styracosaurus.svg","imgPuzzle":"assets/img/puzzle/styracosaurus.svg","url":"dinosaures/styracosaurus.html"},{"slug":"therizinosaurus","nom":"Therizinosaurus","periode":"cretace","famille":"theropodes","regime":"herbivore","longueur":10,"poids":5000,"vitesse":15,"ageDebut":70,"ageFin":68,"lieux":["Asie"],"comparaison":"aussi haut qu’une girafe","accroche":"Les plus longues griffes de toute l’histoire : un mètre de long !","vraiDino":true,"saviezVous":["Pendant 20 ans, on n’a connu que ses griffes : on croyait qu’il s’agissait d’une tortue géante !","Il était couvert de plumes duveteuses.","Il mangeait des feuilles, malgré des allures de monstre de film."],"img":"assets/img/dinos/therizinosaurus.svg","imgPuzzle":"assets/img/puzzle/therizinosaurus.svg","url":"dinosaures/therizinosaurus.html"},{"slug":"gallimimus","nom":"Gallimimus","periode":"cretace","famille":"theropodes","regime":"omnivore","longueur":6,"poids":440,"vitesse":55,"ageDebut":70,"ageFin":68,"lieux":["Asie"],"comparaison":"aussi long qu’une grande voiture","accroche":"L’autruche préhistorique : le sprinteur du monde des dinosaures.","vraiDino":true,"saviezVous":["Son nom veut dire « imitateur de poule ».","C’est lui qu’on voit courir en troupeau dans la scène célèbre de Jurassic Park.","Ses yeux étaient placés sur les côtés de la tête pour surveiller tout autour."],"img":"assets/img/dinos/gallimimus.svg","imgPuzzle":"assets/img/puzzle/gallimimus.svg","url":"dinosaures/gallimimus.html"},{"slug":"oviraptor","nom":"Oviraptor","periode":"cretace","famille":"theropodes","regime":"omnivore","longueur":1.6,"poids":30,"vitesse":40,"ageDebut":75,"ageFin":71,"lieux":["Asie"],"comparaison":"aussi long qu’un vélo","accroche":"Accusé pendant 70 ans de voler des œufs… alors qu’il couvait les siens !","vraiDino":true,"saviezVous":["Son nom complet, Oviraptor philoceratops, veut dire « voleur d’œufs qui aime les cératopsiens » : deux erreurs en un seul nom !","Le plus célèbre squelette de couveur, un cousin appelé Citipati, a été surnommé « Big Mama » par les scientifiques.","Les œufs de sa famille étaient allongés, pondus deux par deux et disposés en cercle. Certains étaient même bleu-vert !","On ne sait pas encore exactement ce qu’il mangeait : des plantes, des coquillages, des petits animaux… sans doute un peu de tout."],"img":"assets/img/dinos/oviraptor.svg","imgPuzzle":"assets/img/puzzle/oviraptor.svg","url":"dinosaures/oviraptor.html"},{"slug":"argentinosaurus","nom":"Argentinosaurus","periode":"cretace","famille":"sauropodes","regime":"herbivore","longueur":35,"poids":70000,"vitesse":8,"ageDebut":96,"ageFin":92,"lieux":["Amérique du Sud"],"comparaison":"aussi long qu’un terrain de basket","accroche":"Le plus grand animal terrestre de tous les temps : 35 mètres et 70 tonnes !","vraiDino":true,"saviezVous":["Un fermier argentin a cru trouver un tronc d’arbre pétrifié : c’était en réalité son tibia !","Son cœur devait peser plus de 300 kilos.","Il pondait des œufs à peine plus gros qu’un pamplemousse, malgré sa taille adulte gigantesque."],"img":"assets/img/dinos/argentinosaurus.svg","imgPuzzle":"assets/img/puzzle/argentinosaurus.svg","url":"dinosaures/argentinosaurus.html"},{"slug":"quetzalcoatlus","nom":"Quetzalcoatlus","periode":"cretace","famille":"pterosaures","regime":"carnivore","longueur":11,"poids":250,"vitesse":90,"ageDebut":68,"ageFin":66,"lieux":["Amérique du Nord"],"comparaison":"aussi large qu’un petit avion","accroche":"Une envergure de 11 mètres : le plus grand animal volant de tous les temps. (Pas un dinosaure !)","vraiDino":false,"saviezVous":["Il porte le nom de Quetzalcóatl, le dieu-serpent à plumes des Aztèques.","Il pouvait planer des centaines de kilomètres sans battre des ailes.","Son cou à lui seul mesurait près de 3 mètres."],"img":"assets/img/dinos/quetzalcoatlus.svg","imgPuzzle":"assets/img/puzzle/quetzalcoatlus.svg","url":"dinosaures/quetzalcoatlus.html"},{"slug":"mosasaurus","nom":"Mosasaurus","periode":"cretace","famille":"reptiles-marins","regime":"carnivore","longueur":17,"poids":14000,"vitesse":48,"ageDebut":70,"ageFin":66,"lieux":["Europe","Amérique du Nord"],"comparaison":"aussi long qu’un autobus et demi","accroche":"Le monstre des mers du Crétacé. (Et non, ce n’est pas un dinosaure !)","vraiDino":false,"saviezVous":["Son crâne a été volé pendant la Révolution française et emmené à Paris !","Il donnait naissance à des petits vivants, en pleine mer.","Il est le cousin lointain du varan de Komodo."],"img":"assets/img/dinos/mosasaurus.svg","imgPuzzle":"assets/img/puzzle/mosasaurus.svg","url":"dinosaures/mosasaurus.html"}];
window.QUIZ = [{"n":1,"q":"Quel dinosaure avait trois cornes sur la tête ?","r":["Le Tricératops","Le Stégosaure","Le Diplodocus","Le Ptérodactyle"],"e":"Deux grandes cornes au-dessus des yeux et une plus petite sur le nez : c’est la signature du Tricératops !"},{"n":1,"q":"Que mangeait le Tyrannosaurus rex ?","r":["De la viande","Des feuilles","Des fleurs","Du poisson uniquement"],"e":"Le T-rex était un carnivore : il chassait d’autres dinosaures et mangeait aussi des animaux déjà morts."},{"n":1,"q":"Qu’est-ce qu’un fossile ?","r":["Un reste d’être vivant conservé dans la roche","Un caillou brillant","Un œuf de dinosaure encore frais","Une empreinte dans le sable de la plage"],"e":"Os, dents, coquilles ou empreintes : tout ce qui se conserve dans la roche pendant des millions d’années."},{"n":1,"q":"Quel animal d’aujourd’hui est un vrai dinosaure ?","r":["Le moineau","Le crocodile","Le lézard","La tortue"],"e":"Les oiseaux descendent directement des dinosaures théropodes. Un moineau est donc un dinosaure vivant !"},{"n":1,"q":"Le Stégosaure portait quoi sur son dos ?","r":["De grandes plaques osseuses","Une bosse de chameau","Une carapace de tortue","Des ailes"],"e":"Deux rangées de plaques disposées en quinconce, comme les tuiles d’un toit."},{"n":1,"q":"Quel était le plus long dinosaure de cette liste ?","r":["L’Argentinosaurus","Le Vélociraptor","Le Compsognathus","L’Archaeopteryx"],"e":"35 mètres de long et 70 tonnes : c’est le plus grand animal terrestre de tous les temps."},{"n":1,"q":"Comment appelle-t-on un scientifique qui étudie les dinosaures ?","r":["Un paléontologue","Un astronome","Un vétérinaire","Un archéologue"],"e":"L’archéologue étudie les humains du passé ; le paléontologue étudie les êtres vivants fossilisés."},{"n":1,"q":"Combien de périodes compte l’ère des dinosaures ?","r":["Trois","Deux","Cinq","Une seule"],"e":"Le Trias, le Jurassique et le Crétacé forment ensemble l’ère appelée Mésozoïque."},{"n":1,"q":"Quel dinosaure avait une massue au bout de la queue ?","r":["L’Ankylosaure","Le Brachiosaure","Le Parasaurolophus","Le Ptéranodon"],"e":"Une boule d’os assez lourde pour casser la patte d’un prédateur !"},{"n":1,"q":"Comment naissaient les bébés dinosaures ?","r":["En sortant d’un œuf","Vivants, comme les chiots","Dans une poche, comme les kangourous","Dans une graine géante"],"e":"Tous les dinosaures pondaient des œufs. Même le géant Argentinosaurus sortait d’un œuf à peine plus gros qu’un pamplemousse !"},{"n":1,"q":"Les dinosaures ont-ils connu les mammouths ?","r":["Non, jamais","Oui, ils vivaient ensemble","Oui, mais seulement au pôle Nord","Seulement les plus gros dinosaures"],"e":"Le mammouth laineux est apparu plus de 65 millions d’années après la disparition des dinosaures."},{"n":1,"q":"Le Vélociraptor était à peu près de la taille…","r":["d’un gros dindon","d’un éléphant","d’un autobus","d’une souris"],"e":"2 mètres de long dont la moitié en queue, 15 kilos, et couvert de plumes. Les films l’ont beaucoup agrandi !"},{"n":2,"q":"Qu’est-ce qui a causé la disparition des dinosaures ?","r":["La chute d’un astéroïde","Une grande sécheresse","Une épidémie","Les chasseurs préhistoriques"],"e":"Un astéroïde de 10 km est tombé au Mexique il y a 66 millions d’années. La poussière a masqué le Soleil pendant des mois."},{"n":2,"q":"Le Ptérodactyle est-il un dinosaure ?","r":["Non, c’est un ptérosaure","Oui, c’est un dinosaure volant","Oui, c’est un dinosaure marin","Non, c’est un oiseau"],"e":"Les ptérosaures sont des cousins des dinosaures, mais forment un groupe à part entière."},{"n":2,"q":"Pendant quelle période vivait le T-rex ?","r":["Le Crétacé","Le Jurassique","Le Trias","La Préhistoire humaine"],"e":"Il a vécu tout à la fin du Crétacé, de −68 à −66 millions d’années."},{"n":2,"q":"Quel est le point commun entre le Spinosaurus et un crocodile ?","r":["Un museau allongé pour pêcher","Une carapace","Quatre pattes courtes","Une queue à écailles carrées"],"e":"Le Spinosaurus pêchait de gros poissons avec son museau étroit et ses dents coniques."},{"n":2,"q":"Que signifie le nom « Tyrannosaurus rex » ?","r":["Le roi des lézards tyrans","Le mangeur d’hommes","La grande bête du nord","Le lézard à trois doigts"],"e":"« Tyrannosaurus » veut dire lézard tyran, et « rex » veut dire roi en latin."},{"n":2,"q":"Quel dinosaure pouvait produire un son de trompette ?","r":["Le Parasaurolophus","Le Tricératops","L’Allosaure","Le Compsognathus"],"e":"Sa crête creuse contenait de longs tubes repliés, exactement comme un trombone."},{"n":2,"q":"Les dinosaures avaient-ils des plumes ?","r":["Beaucoup en avaient","Aucun n’en avait","Tous en avaient","Seuls les plus gros en avaient"],"e":"Surtout les petits carnivores et les raptors. Les plumes servaient à tenir chaud bien avant de servir à voler."},{"n":2,"q":"Quel supercontinent existait au Trias ?","r":["La Pangée","L’Atlantide","La Laurasie seule","Le Gondwana seul"],"e":"Toutes les terres étaient collées en un seul bloc : on pouvait le traverser à pied."},{"n":2,"q":"Quelle est la particularité du Thérizinosaurus ?","r":["Il avait des griffes d’un mètre… et mangeait des plantes","Il volait","Il nageait sous l’eau","Il n’avait pas de queue"],"e":"Ses griffes géantes servaient à rabattre les branches, un peu comme un paresseux géant."},{"n":2,"q":"Où vivait le Mosasaurus ?","r":["Dans l’océan","Dans le désert","Dans les arbres","Dans les montagnes"],"e":"C’était un reptile marin géant, cousin des varans. Attention : ce n’est pas un dinosaure !"},{"n":2,"q":"Qu’est-ce qu’un gastrolithe ?","r":["Un caillou avalé pour broyer les plantes","Un os de la patte","Une écaille fossilisée","Un œuf pétrifié"],"e":"Les sauropodes ne mâchaient pas : ils avalaient des pierres qui écrasaient la nourriture dans l’estomac."},{"n":2,"q":"Que veut dire le nom « Maiasaura » ?","r":["Le lézard bonne mère","Le lézard qui court vite","Le roi des marais","La reine des œufs"],"e":"On a retrouvé ses nids pleins de bébés : ses parents s’occupaient de leurs petits."},{"n":2,"q":"Pourquoi les sauropodes enterraient-ils leurs œufs au lieu de les couver ?","r":["Ils étaient bien trop lourds pour s’asseoir dessus","Ils avaient peur du noir","Ils n’aimaient pas leurs bébés","Pour les cacher des humains"],"e":"Avec plusieurs dizaines de tonnes, impossible de couver sans tout écraser ! La chaleur du sol faisait le travail."},{"n":2,"q":"Combien de doigts touchent le sol dans une empreinte de raptor ?","r":["Deux","Trois","Cinq","Un seul"],"e":"Leur grande griffe en faucille restait relevée pour ne pas s’user : seuls deux doigts laissaient une trace."},{"n":2,"q":"Y avait-il de grandes calottes de glace pendant le règne des dinosaures ?","r":["Non, la Terre était plutôt chaude","Oui, partout sur Terre","Oui, au milieu des continents","Seulement au Jurassique"],"e":"Des forêts poussaient jusque près des pôles. La grande glaciation a eu lieu bien avant eux, et d’autres bien après."},{"n":2,"q":"Quel dinosaure portait un casque en os épais de 25 cm ?","r":["Le Pachycéphalosaure","Le Diplodocus","Le Gallimimus","L’Iguanodon"],"e":"Son crâne bombé encaissait des chocs violents lors des combats entre mâles."},{"n":3,"q":"Combien de temps sépare le dernier T-rex du premier humain ?","r":["Environ 66 millions d’années","Environ 1 million d’années","Environ 10 000 ans","Ils ont vécu à la même époque"],"e":"Les humains et les dinosaures non-aviens ne se sont jamais croisés, sauf dans les dessins animés !"},{"n":3,"q":"Quelle est la morsure la plus puissante jamais mesurée chez un animal terrestre ?","r":["Celle du Tyrannosaurus rex","Celle du lion","Celle du crocodile marin","Celle de l’Ankylosaure"],"e":"Environ 35 000 newtons, soit 5 tonnes de pression : il broyait les os."},{"n":3,"q":"Pourquoi ne peut-on pas recréer un dinosaure à partir de son ADN ?","r":["L’ADN se détruit en moins d’un million d’années","On n’a pas les bonnes machines","C’est interdit par la loi","Les œufs sont trop petits"],"e":"Après 66 millions d’années, il ne reste plus aucune molécule d’ADN exploitable."},{"n":3,"q":"De quelle couleur était le Microraptor ?","r":["Noir avec des reflets bleutés","Vert vif","Rose et jaune","On n’en a aucune idée"],"e":"Les structures microscopiques de ses plumes fossilisées ont permis de retrouver sa couleur exacte."},{"n":3,"q":"Quel dinosaure est le plus long carnivore terrestre connu ?","r":["Le Spinosaurus","Le Tyrannosaurus rex","L’Allosaurus","Le Carnotaurus"],"e":"15 mètres contre 12 pour le T-rex. Mais le T-rex était bien plus massif et plus puissant."},{"n":3,"q":"Quel fossile a prouvé le lien entre dinosaures et oiseaux ?","r":["L’Archaeopteryx","Le Diplodocus","L’Iguanodon","Le Mosasaurus"],"e":"Il possède des plumes et des ailes, mais aussi des dents, des griffes aux ailes et une queue osseuse."},{"n":3,"q":"Qu’est-ce qu’un coprolithe ?","r":["Une crotte fossilisée","Un œuf fossilisé","Une empreinte de pas","Un morceau d’ambre"],"e":"Elles sont précieuses : elles racontent exactement ce que l’animal avait mangé."},{"n":3,"q":"Sur quel continent a-t-on trouvé le Cryolophosaurus ?","r":["En Antarctique","En Australie","En Afrique","En Europe"],"e":"À l’époque, l’Antarctique n’était pas gelé : c’était une forêt tempérée !"},{"n":3,"q":"Pourquoi le T-rex avait-il de si petits bras ?","r":["Ils étaient courts mais très musclés, utiles pour maintenir une proie","Ils ne servaient à rien du tout","Ils repoussaient chaque année","Ils servaient à voler"],"e":"Chaque bras pouvait soulever plus de 200 kilos malgré sa petite taille."},{"n":3,"q":"Quel animal volant a battu tous les records de taille ?","r":["Le Quetzalcoatlus","L’aigle royal","L’Archaeopteryx","Le Ptérodactyle"],"e":"11 mètres d’envergure, soit la taille d’un petit avion. C’est un ptérosaure, pas un dinosaure."},{"n":3,"q":"Qui a découvert le premier crâne complet d’Ichthyosaure ?","r":["Mary Anning, à 12 ans","Charles Darwin","Barnum Brown","Un ingénieur de la NASA"],"e":"Cette jeune Anglaise est devenue l’une des plus grandes chasseuses de fossiles de l’histoire."},{"n":3,"q":"Pourquoi l’Oviraptor porte-t-il un nom injuste ?","r":["On l’a accusé de voler des œufs… qui étaient les siens","Il ne savait pas courir","Il n’a jamais vécu en Mongolie","Il mangeait seulement des fruits"],"e":"En 1993, on a découvert un bébé de sa famille dans un œuf identique : il couvait ses propres œufs !"},{"n":3,"q":"De quelle couleur étaient les œufs du Deinonychus ?","r":["Bleus avec des taches brunes","Tout blancs","Rouges et jaunes","On n’en a aucune idée"],"e":"Des traces de pigments retrouvées dans la coquille fossilisée ont révélé leur couleur, comme chez certains oiseaux."},{"n":3,"q":"Où se trouve la plus longue piste de sauropode connue au monde ?","r":["À Plagne, dans l’Ain","À Paris, sous la tour Eiffel","Au Groenland","En Antarctique"],"e":"Un sauropode y a laissé 110 pas sur 155 mètres, il y a 150 millions d’années."},{"n":3,"q":"Comment appelle-t-on les pointes au bout de la queue du Stégosaure ?","r":["Le thagomizer","Le tridactyle","Le sacrum","Le pterygoïde"],"e":"Ce nom vient d’une bande dessinée humoristique… et les scientifiques l’ont vraiment adopté !"}];
window.VRAIFAUX = [{"a":"Les humains et les dinosaures ont vécu à la même époque.","v":false,"e":"66 millions d’années les séparent. Aucun humain n’a jamais vu un dinosaure vivant, sauf un oiseau !"},{"a":"Les oiseaux sont des dinosaures.","v":true,"e":"Ils descendent directement des dinosaures théropodes. Ce sont les seuls survivants du groupe."},{"a":"Le Ptérodactyle était un dinosaure volant.","v":false,"e":"C’est un ptérosaure : un cousin des dinosaures, pas un dinosaure."},{"a":"Tous les dinosaures étaient gigantesques.","v":false,"e":"Le Compsognathus faisait la taille d’une poule, et beaucoup d’autres étaient tout petits."},{"a":"Le Vélociraptor avait des plumes.","v":true,"e":"On a retrouvé sur ses os les attaches de plumes, identiques à celles des oiseaux actuels."},{"a":"Le Tricératops et le T-rex ont vécu à la même époque.","v":true,"e":"Tous deux vivaient en Amérique du Nord à la toute fin du Crétacé. Ils se croisaient vraiment."},{"a":"Le Stégosaure avait un cerveau de la taille d’une prune.","v":true,"e":"Environ 80 grammes pour un corps de 5 tonnes. Brouter des fougères ne demande pas beaucoup de réflexion."},{"a":"Les dinosaures vivaient aussi dans l’océan.","v":false,"e":"Aucun dinosaure n’était marin. Les monstres des mers étaient des reptiles marins, comme le Mosasaurus."},{"a":"Le Spinosaurus savait nager.","v":true,"e":"Sa queue plate en forme de rame, découverte en 2020, le prouve : c’est le seul dinosaure vraiment aquatique connu."},{"a":"Un astéroïde a mis fin au règne des dinosaures.","v":true,"e":"Il a frappé le Mexique il y a 66 millions d’années et laissé un cratère de 180 km de large."},{"a":"Les dinosaures crachaient du feu.","v":false,"e":"Aucun animal connu n’a jamais craché de feu. C’est réservé aux dragons des histoires !"},{"a":"Le T-rex pouvait courir à 60 km/h.","v":false,"e":"Environ 20 à 25 km/h. Avec 8 tonnes, une chute à pleine vitesse lui aurait été fatale."},{"a":"Certains dinosaures avalaient des cailloux exprès.","v":true,"e":"Ce sont les gastrolithes : ils broyaient les plantes dans l’estomac, faute de pouvoir mâcher."},{"a":"L’Argentinosaurus pesait autant que 14 éléphants.","v":true,"e":"Environ 70 tonnes : c’est le plus grand animal ayant jamais marché sur la terre ferme."},{"a":"On connaît la couleur de tous les dinosaures.","v":false,"e":"On ne la connaît que pour quelques-uns, comme le Microraptor, grâce aux pigments fossilisés de leurs plumes."},{"a":"Le Thérizinosaurus mangeait des plantes malgré ses griffes géantes.","v":true,"e":"Ses griffes d’un mètre servaient à attraper les branches, pas à chasser."},{"a":"Les dinosaures pondaient des œufs.","v":true,"e":"On a retrouvé des nids entiers, parfois avec des embryons encore à l’intérieur."},{"a":"Le Brachiosaure pouvait brouter au sommet des arbres.","v":true,"e":"Sa tête montait à 13 mètres de haut, comme un immeuble de 4 étages."},{"a":"Tous les dinosaures ont disparu il y a 66 millions d’années.","v":false,"e":"Presque tous. Les oiseaux ont survécu : il en existe environ 11 000 espèces aujourd’hui."},{"a":"On peut cloner un dinosaure comme dans les films.","v":false,"e":"L’ADN se détruit complètement en moins d’un million d’années. Il n’en reste plus rien."},{"a":"L’Ankylosaure pouvait casser la patte d’un T-rex.","v":true,"e":"Sa massue de queue frappait assez fort pour briser un os. Un prédateur blessé était condamné."},{"a":"Le Diplodocus mâchait longuement sa nourriture.","v":false,"e":"Il ne mâchait pas du tout : il peignait les feuilles avec ses dents et avalait tout rond."},{"a":"Les dinosaures vivaient tous sur le même continent.","v":false,"e":"C’était vrai au Trias avec la Pangée, mais les continents se sont séparés ensuite."},{"a":"Les dinosaures ont vécu pendant une ère glaciaire, avec les mammouths.","v":false,"e":"Il n’y avait pas de grandes calottes de glace pendant leur règne, et les mammouths sont apparus 65 millions d’années après eux."},{"a":"Certains dinosaures pondaient des œufs à coquille molle.","v":true,"e":"C’était le cas du Protoceratops : sa coquille était souple comme celle des œufs de tortue."},{"a":"On connaît les œufs du T-rex.","v":false,"e":"Aucun œuf n’a encore pu lui être attribué. Pour en être sûr, il faudrait trouver un bébé T-rex dans son œuf !"},{"a":"Des dinosaures vivaient près des pôles, avec des hivers sombres et enneigés.","v":true,"e":"En Alaska, on a même retrouvé des bébés dinosaures : ils naissaient sur place, malgré l’hiver."},{"a":"L’Oviraptor volait les œufs des autres dinosaures.","v":false,"e":"On l’a cru pendant 70 ans, mais les œufs sur lesquels on l’a trouvé étaient sûrement les siens : il les couvait !"},{"a":"Le Mosasaurus pondait ses œufs sur la plage, comme les tortues.","v":false,"e":"Il donnait naissance à des bébés vivants, directement dans la mer."},{"a":"Un dinosaure a été découvert en France.","v":true,"e":"Plusieurs ! Le Compsognathus a notamment été trouvé dans le Var, et de nombreux œufs en Provence."}];
